scripts.modular_exp:
def solve(inputs: dict) -> float:
    base = inputs['BASE']
    exp = inputs['EXP']
    mod = inputs['MOD']
    return pow(base, exp, mod)

scripts.lcg_counter:
def solve(inputs: dict) -> float:
    X = inputs['SEED']
    A = inputs['A']
    B = inputs['B']
    M = inputs['M']
    K = inputs['K']

    for _ in range(K):
        X = (A * X + B) % M

    return float(X)

scripts.dot_product:
def solve(inputs: dict) -> float:
    quantities = inputs['QUANTITIES']
    prices = inputs['PRICES']
    total = sum(q * p for q, p in zip(quantities, prices))
    return float(total)

